@@ -27,6 +27,7 @@ static dissector_handle_t git_handle;

 static int proto_git = -1;
 static expert_field ei_git_bad_pkt_len = EI_INIT;
+static expert_field ei_git_malformed = EI_INIT;

 static gint ett_git = -1;

